{
  "name": "opencode-work-context",
  "type": "module",
  "version": "0.6.0",
  "description": "Filesystem work-context core and OpenCode adapter",
  "license": "MIT",
  "author": {
    "name": "Nikita Mosiyash",
    "email": "nikita.mosiyash@gmail.com"
  },
  "keywords": [
    "opencode",
    "work-context",
    "workflow",
    "developer-tools"
  ],
  "engines": {
    "node": ">=20"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/mosiyash/opencode-work-context.git"
  },
  "homepage": "https://github.com/mosiyash/opencode-work-context#readme",
  "bugs": {
    "url": "https://github.com/mosiyash/opencode-work-context/issues"
  },
  "bin": {
    "opencode-work-context": "bin/opencode-work-context.js"
  },
  "scripts": {
    "check:language": "node scripts/check-repository-language.js",
    "prepublishOnly": "npm run check:language",
    "test": "node --test",
    "test:integration": "node --test test/integration/*.test.js",
    "test:tui": "OPENCODE_TUI_SMOKE=1 bun --conditions=browser test test/stages-tui.test.js"
  },
  "files": [
    "bin",
    "commands",
    "plugin",
    "src",
    "tools",
    "README.md",
    "LICENSE"
  ],
  "dependencies": {
    "@opentui/solid": "^0.4.5",
    "solid-js": "1.9.12",
    "zod": "^4.6.7"
  },
  "exports": {
    ".": "./src/index.js",
    "./adapter": "./src/opencode-adapter.js",
    "./plugin": "./plugin/work-context.js",
    "./server": "./plugin/server.js",
    "./tui": "./plugin/tui.js",
    "./tools/*": "./tools/*.js"
  }
}
